type LanguageContextValue = { locale: Locale; setLocale: (locale: Locale) => void; t: (key: MessageKey, values?: Record<string, string | number>) => string; formatDate: (date: string) => string };
const LanguageContext = createContext<LanguageContextValue | null>(null);

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(() => sessionStorage.getItem("apaar-locale") === "hi" ? "hi" : "en");
  const setLocale = (next: Locale) => {
    sessionStorage.setItem("apaar-locale", next);
    setLocaleState(next);
  };
  useEffect(() => { document.documentElement.lang = locale; }, [locale]);
  const value = useMemo<LanguageContextValue>(() => ({
    locale,
    setLocale,
    t: (key, values = {}) => {
      const template = locale === "hi" ? hindi[key] : messages[key];
      return template.replace(/\{(\w+)\}/g, (_, name: string) => String(values[name] ?? `{${name}}`));
    },
    formatDate: (date) => new Intl.DateTimeFormat(locale === "hi" ? "hi-IN" : "en-IN", { dateStyle: "medium", timeStyle: "short" }).format(new Date(date)),
  }), [locale]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  const value = useContext(LanguageContext);
  if (!value) throw new Error("useLanguage must be used within LanguageProvider");
  return value;
}

export function localizeApiMessage(message: string, locale: Locale, fallback: string) {
  if (locale === "en") return message;
  const known: Record<string, string> = {
    "Email or password is incorrect.": hindi["login.invalid"],
    "The request could not be completed.": hindi["error.request"],
    "You do not have access to this page.": hindi["error.denied"],
    "Too many sign-in attempts. Wait before trying again.": hindi["api.tooManyLogins"],
    "Enter a valid email and password.": hindi["api.enterCredentials"],
    "Sign-in is temporarily unavailable.": hindi["api.signInUnavailable"],
    "Sign-out could not be completed.": hindi["api.signOutFailed"],
    "Could not load student records.": hindi["institution.loadError"],
    "Could not load demo records.": hindi["student.loadError"],
    "The confirmation could not be recorded.": hindi["api.confirmError"],
    "The discrepancy could not be recorded.": hindi["api.discrepancyError"],
    "An open or in-review discrepancy with the same claim and reason already exists.": hindi["student.duplicateDiscrepancy"],
    "Could not load discrepancy reports.": hindi["review.apiLoadError"],
    "Could not save the review update.": hindi["review.saveError"],
    "The discrepancy review could not be saved.": hindi["api.reviewSaveError"],
    "Choose one or more valid record fields and provide a correction reason of 10–1000 characters.": hindi["correction.invalid"],
    "At least one submitted field must differ from the current institution record.": hindi["correction.noChanges"],
    "A record with this reference already exists in your institution.": hindi["correction.duplicateReference"],
    "Correction history is temporarily unavailable.": hindi["correction.history.loadError"],
    "No student record exists in this institution scope.": hindi["correction.historyDenied"],
    "The student record correction could not be saved.": hindi["correction.apiError"],
    "Discrepancy reports are temporarily unavailable.": hindi["review.apiLoadError"],
    "Student records are temporarily unavailable.": hindi["institution.loadError"],
    "Page must be positive and pageSize must be between 1 and 50.": hindi["api.studentPageSize"],
    "Page must be positive and pageSize must be between 1 and 100.": hindi["api.institutionPageSize"],
    "Invalid discrepancy list filters.": hindi["api.invalidDiscrepancyFilters"],
    "No discrepancy reports match this institution scope.": hindi["api.noReportsInScope"],
    "No discrepancy report exists in this institution scope.": hindi["api.noReportInScope"],
    "Resolved reports cannot be changed.": hindi["api.resolvedImmutable"],
    "Choose a CSV file to import.": hindi["api.csvChoose"],
    "The import could not be confirmed. Review the listed rows and check the record list before retrying.": hindi["api.importUnconfirmed"],
    "Upload one CSV file using the file field.": hindi["api.csvUpload"],
    "Choose a valid institution, program, and review status.": hindi["api.validAicteFilters"],
    "No synthetic institution matches this filter.": hindi["api.noInstitution"],
    "The CSV file could not be parsed.": hindi["csv.reason.parse"],
    "The CSV file is empty.": hindi["csv.reason.empty"],
    "The CSV headers are invalid.": hindi["csv.reason.invalidHeaders"],
    "The CSV could not be imported.": hindi["institution.import.error"],
    "Could not load the oversight summary.": hindi["aicte.apiError"],
    "The synthetic oversight summary is temporarily unavailable.": hindi["aicte.apiError"],
    "Demo student records are temporarily unavailable.": hindi["student.loadError"],
    "Synthetic demo records are unavailable.": hindi["student.unavailable"],
    "Demo confirmation recorded. It does not verify identity or official APAAR status.": hindi["api.demoConfirmSuccess"],
    "Discrepancy recorded for review. The institution-reported value was preserved.": hindi["api.discrepancySuccess"],
    "Provide a valid affected field, claimed value, and reason (10–1000 characters).": hindi["api.studentInput"],
    "The claimed value must differ from the institution-reported value.": hindi["api.sameValue"],
    "The selected synthetic record was not found.": hindi["api.recordMissing"],
    "The linked synthetic record was not found.": hindi["api.recordMissing"],
    "This student account has no linked synthetic record.": hindi["api.recordNotLinked"],
    "Only .csv files are accepted.": hindi["api.csvOnly"],
    "Choose UNDER_REVIEW or RESOLVED and provide a 5–1000 character review note.": hindi["api.reviewNoteInvalid"],
  };
  if (known[message]) return known[message];
  const reasonKeys: Record<string, MessageKey> = {
    "Reference must contain at least 2 characters.": "csv.reason.referenceMin",
    "Reference must contain at most 40 characters.": "csv.reason.referenceMax",
    "Synthetic references must start with SYNTH- and contain only letters, numbers, hyphens, or underscores.": "csv.reason.referenceFormat",
    "Full name must contain at least 2 characters.": "csv.reason.nameMin",
    "Full name must contain at most 120 characters.": "csv.reason.nameMax",
    "Full name contains unsupported characters.": "csv.reason.nameFormat",
    "Program must contain at least 2 characters.": "csv.reason.programMin",
    "Program must contain at most 120 characters.": "csv.reason.programMax",
    "Program contains unsupported characters.": "csv.reason.programFormat",
    "Column names must not be blank.": "csv.reason.blankColumn",
    "Check UTF-8 encoding, quoting, and CSV delimiters.": "csv.reason.parse",
    "A header row is required.": "csv.reason.header",
    "Maximum 500 data rows per file.": "csv.reason.maxRows",
  };
  if (reasonKeys[message]) return hindi[reasonKeys[message]];
  let match = message.match(/^The CSV exceeds the (\d+)-row limit; no rows were imported\.$/);
  if (match) return hindi["csv.reason.tooManyRows"].replace("{maximum}", match[1]);
  match = message.match(/^Maximum (\d+) data rows per file\.$/);
  if (match) return hindi["csv.reason.maxRows"].replace("{maximum}", match[1]);
  match = message.match(/^Expected (\d+) fields but found (\d+)\.$/);
  if (match) return hindi["csv.reason.fields"].replace("{expected}", match[1]).replace("{found}", match[2]);
  match = message.match(/^Missing required column: (.+)\.$/);
  if (match) return `आवश्यक कॉलम नहीं है: ${match[1]}.`;
  match = message.match(/^Column (.+) appears more than once\.$/);
  if (match) return `कॉलम ${match[1]} एक से अधिक बार दिया गया है।`;
  match = message.match(/^Unexpected column: (.+)\.$/);
  if (match) return `अनपेक्षित कॉलम: ${match[1]}.`;
  match = message.match(/^Possible duplicate of existing reference (.+); flagged for review and not imported\.$/);
  if (match) return `मौजूदा संदर्भ ${match[1]} का संभावित डुप्लिकेट; समीक्षा के लिए रोका गया और आयात नहीं हुआ।`;
  match = message.match(/^Possible duplicate within this upload \(rows (\d+) and (\d+)\); both rows are flagged for review and not imported\.$/);
  if (match) return `इस अपलोड में संभावित डुप्लिकेट (पंक्तियाँ ${match[1]} और ${match[2]}); दोनों पंक्तियाँ समीक्षा के लिए रोकी गईं और आयात नहीं हुईं।`;
  match = message.match(/^Possible duplicate of (.+) in (.+); flagged for review and not imported\.$/);
  if (match) return `${match[1]} का ${match[2]} में संभावित डुप्लिकेट; समीक्षा के लिए रोका गया और आयात नहीं हुआ।`;
  return fallback;
}
